SELECT 'batch_017_cd16c784_wav_08' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-08c5fd9b-a07','sm-upload-0f6e0515-62c','sm-upload-5979a6ff-f6c','sm-upload-746012d3-887','sm-upload-75a8634a-1b1','sm-upload-8aa9653f-bb6','sm-upload-9ac28768-466','sm-upload-b4e17f3c-27c') AND album_id='al-44bf6641ecfaf08f307a0587cd16c784') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-08c5fd9b-a07','sm-upload-0f6e0515-62c','sm-upload-5979a6ff-f6c','sm-upload-746012d3-887','sm-upload-75a8634a-1b1','sm-upload-8aa9653f-bb6','sm-upload-9ac28768-466','sm-upload-b4e17f3c-27c') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-44bf6641ecfaf08f307a0587cd16c784' AND name='低语者') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-44bf6641ecfaf08f307a0587cd16c784') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-44bf6641ecfaf08f307a0587cd16c784') AS calculated_size;
